<script setup lang="ts">
import { canForceDelete } from '~/utils/destructive-confirmation'

type Detail={tenant:{id:string;name:string;slug:string;plan:string;status:string;billing_email?:string};member_count:number;project_count:number;feedback_count:number}
type Audit={events:Array<{id:string;kind:string;actor_type:string;action?:string;outcome?:string;created_at:string}>}
const route=useRoute();const {$platformApi}=useNuxtApp();const id=String(route.params.id)
const [{data:detail,error},{data:audit}]=await Promise.all([useAsyncData(`workspace:${id}`,()=> $platformApi<Detail>(`/admin/backoffice/tenants/${id}`),{server:false}),useAsyncData(`audit:${id}`,()=> $platformApi<Audit>(`/admin/backoffice/tenants/${id}/access-events`),{server:false})])
const typedSlug=ref('');const deleting=ref(false);const deleteError=ref('');const canDelete=computed(()=>detail.value?canForceDelete(typedSlug.value,detail.value.tenant.slug):false)
async function forceDelete(){if(!detail.value||!canDelete.value||deleting.value)return;deleting.value=true;deleteError.value='';try{await $platformApi(`/admin/tenants/${id}`,{method:'DELETE'});await navigateTo('/workspaces')}catch{deleteError.value='The workspace could not be deleted. No change was confirmed.'}finally{deleting.value=false}}
</script>
<template><section v-if="detail"><p class="eyebrow">Workspace / {{ detail.tenant.slug }}</p><h1 class="title">{{ detail.tenant.name }}</h1><div class="metrics"><article class="metric"><b>{{ detail.member_count }}</b><span>Members</span></article><article class="metric"><b>{{ detail.project_count }}</b><span>Projects</span></article><article class="metric"><b>{{ detail.feedback_count }}</b><span>Feedback items</span></article><article class="metric"><b>{{ detail.tenant.plan }}</b><span>{{ detail.tenant.status }}</span></article></div><section class="panel"><p class="eyebrow">Audit ledger</p><table class="table"><thead><tr><th>Event</th><th>Actor</th><th>Outcome</th><th>When</th></tr></thead><tbody><tr v-for="event in audit?.events" :key="event.id"><td>{{ event.kind }}</td><td>{{ event.actor_type }}</td><td>{{ event.outcome||'—' }}</td><td>{{ new Date(event.created_at).toLocaleString() }}</td></tr></tbody></table></section><section class="panel"><p class="eyebrow error">Danger zone</p><h2>Force-delete this workspace</h2><p class="muted">This runs the platform’s audited deletion executor. Type <b>{{ detail.tenant.slug }}</b> exactly to enable it.</p><input v-model="typedSlug" :placeholder="detail.tenant.slug" aria-label="Confirm workspace slug"><button class="button" :disabled="!canDelete||deleting" @click="forceDelete">{{ deleting?'Deleting…':'Force delete workspace' }}</button><p v-if="deleteError" class="error" role="alert">{{ deleteError }}</p></section></section><section v-else><h1 class="title">Workspace unavailable</h1><p class="error">{{ error?'The workspace could not be loaded.':'Loading…' }}</p></section></template>
